    char [] strChars = str.toCharArray ();
    List<Character> word = new ArrayList <> ();
    for (char c : strChars) {
        word.add (c);
    }
    while (true) {
        if ((word.size () == 1) || (word.size () == 0)) {
            return true;
        }
        if (word.get (0).equalsIgnoreCase(word.get (word.size () - 1))) {
            word.remove (0);
            word.remove (word.size () - 1);
        } else {
            return false;
        }
    }
}

